INSERT INTO issue_comment (issue_id,user_id,content) SELECT i.issue_id,(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'시연용 점검 항목입니다. 실제 결과 확인 후 상태를 갱신해 주세요.' FROM issue i WHERE i.project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='신세계몰 계정관리' ORDER BY project_id LIMIT 1) AND i.title='[DEMO] 계정관리 - 로그아웃 점검' AND NOT EXISTS (SELECT 1 FROM issue_comment c WHERE c.issue_id=i.issue_id AND c.user_id=(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1) AND c.content='시연용 점검 항목입니다. 실제 결과 확인 후 상태를 갱신해 주세요.');
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='신세계몰 계정관리' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'DEMO-003','계정관리 - 회원 탈퇴','로그인 상태','탈퇴 안내 확인 후 탈퇴 요청','정책에 따른 탈퇴 처리','4','시연용 가상 결과 / 제공된 테스트케이스의 주제를 참고해 재구성 / 실제 재검증 아님',NULL) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
