INSERT INTO project (owner_id,title,description,status,start_date,due_date) SELECT (SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1),'토스 앱 기능','제공된 QA 테스트케이스를 바탕으로 구성한 포트폴리오 시연용 프로젝트. 기록된 판정은 원본 자료의 과거 결과이며 현재 재검증한 결과가 아닙니다.','0',CURRENT_DATE(),DATE_ADD(CURRENT_DATE(),INTERVAL 30 DAY) WHERE NOT EXISTS (SELECT 1 FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='토스 앱 기능');
