INSERT INTO issue (project_id,reporter_id,assignee_id,title,content,type,status,priority) SELECT (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='토스 앱 기능' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),(SELECT user_id FROM users WHERE email='dev@idi.test' LIMIT 1),'[DEMO] [TOSS-020] 송금 - 송금 금액 - 한도 초과','원본 테스트케이스 TOSS-020 / 판정 Block. 기대 결과: 허용 한도를 초과한 송금이 제한되고 한도 관련 안내가 표시됨. 원본 비고: 송금 한도 초과 조건을 재현하기 위해 필요한 실제 자금 조건이 부족하여 테스트 수행이 제한됨.. 테스트 조건 부족 등으로 판정이 보류된 항목입니다. 확정 결함이 아닙니다.','0','0','1' WHERE NOT EXISTS (SELECT 1 FROM issue WHERE project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='토스 앱 기능' ORDER BY project_id LIMIT 1) AND title='[DEMO] [TOSS-020] 송금 - 송금 금액 - 한도 초과');
