INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) SELECT (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'TC-041','차량 삭제 - 등록된 차량 삭제','기기에 등록된 차량','1. 등록 차량 삭제 진행','삭제 전 별도의 확인 절차를 거친 뒤 삭제가 진행된다.','0','원본 분류: 정상 흐름. 원본 판정: Pass. 신규 재검증 아님. 원본 비고: 차량번호를 입력해야 삭제가 진행됨',CURRENT_TIMESTAMP WHERE (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) IS NOT NULL AND (SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM test_case WHERE project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) AND case_code='TC-041');
INSERT INTO issue (project_id,reporter_id,assignee_id,title,content,type,status,priority) SELECT (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),(SELECT user_id FROM users WHERE email='dev@idi.test' LIMIT 1),'[BUG-01] [차량번호 입력] 특수문자 입력 시 형식 오류 문구가 잠깐 노출된 뒤 사라짐','관련 TC: TC-017\n구분: 결함 (입력값 검증)\n테스트 환경: Galaxy S24 / Android 16 / 앱 버전 2024.10.03\n테스트 데이터: 입력값 ''.?''\n발생 빈도: 3회 중 3회\n심각도: 중간\n심각도 근거: 잘못된 값인데도 오류 표시가 사라지고 ''확인'' 버튼이 활성 상태로 보여, 사용자가 정상 입력으로 오해할 수 있음\n발견한 문제: 차량번호 입력 칸에 특수문자를 입력하면 형식 오류 문구가 잠깐 보였다가 사라져서 별도의 오류가 아닌 것처럼 인식할 여지가 있음\n사전 조건: 차량번호 입력 화면, 키보드 기호 자판 사용\n재현 방법: 1. 차량번호 입력 칸 선택\n2. 기호 자판에서 ''.'' ''?'' 입력\n3. 안내 문구·입력 칸 테두리·''확인'' 버튼 상태 확인\n4. ''확인'' 버튼 탭\n기대 동작: 허용되지 않는 문자는 입력되지 않거나, 형식 오류 안내가 유지되고 ''확인''으로 다음 단계에 진행되지 않음\n실제 동작: 오류 문구가 잠깐 노출된 뒤 사라지고, 입력 칸이 정상 상태(파란 테두리)로 바뀌며 ''확인'' 버튼이 활성 상태로 표시(''확인'' 탭 시 다음 단계로 진행되지 않음)\n개선 제안: 입력 단계에서 허용 문자(숫자·한글)만 받도록 제한하거나, 입력값이 고쳐질 때까지 오류 안내를 유지','0','0','1' WHERE (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) IS NOT NULL AND (SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM issue WHERE project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) AND title='[BUG-01] [차량번호 입력] 특수문자 입력 시 형식 오류 문구가 잠깐 노출된 뒤 사라짐');
INSERT INTO issue (project_id,reporter_id,assignee_id,title,content,type,status,priority) SELECT (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),(SELECT user_id FROM users WHERE email='dev@idi.test' LIMIT 1),'[BUG-02] [차량번호 입력] 키보드 노출 시 ''번호없이 등록하기'' 버튼이 다른 요소와 겹쳐 보이지 않음','관련 TC: TC-011, TC-012\n구분: 결함 (UI 레이아웃)\n테스트 환경: Galaxy S24 / Android 16 / 앱 버전 2024.10.03\n테스트 데이터: 입력값 ''10'' (키보드 노출 상태)\n발생 빈도: 5회 중 5회\n심각도: 낮음\n심각도 근거: 키보드를 내리면 다시 선택할 수 있어 기능은 쓸 수 있지만, 입력 중에는 대체 등록 방법을 찾기 어려움\n발견한 문제: 차량번호를 입력하려고 키보드를 올리면 ''번호없이 등록하기'' 버튼이 ''개인정보 수집 항목 보기'' 링크와 겹쳐 가려짐\n사전 조건: 차량번호 입력 화면\n재현 방법: 1. 차량번호 입력 칸 선택 (키보드 노출)\n2. ''번호없이 등록하기'' 버튼 위치 확인\n3. 키보드를 닫은 뒤 ''번호없이 등록하기'' 선택\n기대 동작: 키보드가 올라와도 ''번호없이 등록하기'' 버튼이 다른 요소와 겹치지 않고 보임\n실제 동작: 버튼이 흐리게 가려지고 ''개인정보 수집 항목 보기'' 링크와 겹쳐 보임 (위: 키보드 전 / 아래: 키보드 노출 후)\n키보드를 닫았을 때는 정상화면으로 돌아옴\n개선 제안: 키보드가 올라오면 버튼을 키보드 위로 옮기거나, 링크와 겹치지 않도록 배치 조정','0','0','2' WHERE (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) IS NOT NULL AND (SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM issue WHERE project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) AND title='[BUG-02] [차량번호 입력] 키보드 노출 시 ''번호없이 등록하기'' 버튼이 다른 요소와 겹쳐 보이지 않음');
INSERT INTO issue (project_id,reporter_id,assignee_id,title,content,type,status,priority) SELECT (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),(SELECT user_id FROM users WHERE email='dev@idi.test' LIMIT 1),'[BUG-03] [등록 실패] 네트워크 끊김 시 원인 안내 없이 ''번호없이 등록''을 권유함','관련 TC: TC-005, TC-035\n구분: 개선 건의 사항\n테스트 환경: Galaxy S24 / Android 16 / 앱 버전 2024.10.03\n테스트 데이터: 테스트 차량 (부모님 소유)\n발생 빈도: 3회 중 3회\n심각도: 중간\n심각도 근거: 원인을 모르는 사용자가 ''번호없이 등록''을 선택하면 차량번호 기반 맞춤 관리를 쓰지 못하게 될 수 있음\n발견한 문제: 네트워크가 끊긴 상태에서 차량 등록을 진행하면, 실패 원인(네트워크) 안내 없이 ''번호없이 등록''을 권유하는 팝업만 노출됨\n사전 조건: 소유자명 입력 화면에서 비행기 모드 실행\n재현 방법: 1. 차량번호·소유자명 입력\n2. 비행기 모드 ON\n3. 등록 진행\n4. 팝업 문구 확인\n5. ''재시도'' 탭\n기대 동작: 실패 사유가 네트워크 문제임을 알 수 있고, 연결 후 재시도\n실제 동작: ''차량 등록에 실패했어요 / 차량번호 없이도 등록하고 관리할 수 있어요'' 팝업과 ''재시도'', ''번호없이 등록'' 버튼만 노출되고, 실패 사유는 표시되지 않음\n개선 제안: ''네트워크 연결을 확인해 주세요''처럼 실패 원인을 알려주고, 연결 후 재시도를 먼저 안내','1','0','1' WHERE (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) IS NOT NULL AND (SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM issue WHERE project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) AND title='[BUG-03] [등록 실패] 네트워크 끊김 시 원인 안내 없이 ''번호없이 등록''을 권유함');
INSERT INTO issue (project_id,reporter_id,assignee_id,title,content,type,status,priority) SELECT (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),(SELECT user_id FROM users WHERE email='dev@idi.test' LIMIT 1),'[BUG-04] [앱 시작] 카카오로 시작한 뒤 차량번호 없이 종료하면, 재실행 시 시작 화면 없이 차량번호 입력 화면으로 바로 이동함','관련 TC: TC-006, TC-002\n구분: 개선 건의 사항\n테스트 환경: Galaxy S24 / Android 16 / 앱 버전 2024.10.03\n테스트 데이터: 카카오 계정 로그인, 차량 미등록 상태\n발생 빈도: 3회 중 3회\n심각도: 낮음\n심각도 근거: 차량번호를 입력하면 정상 사용은 가능하지만, 다른 계정으로 바꾸거나 ''가입없이 시작하기''를 다시 고르려는 사용자는 방법을 찾기 어려움\n발견한 문제: ''카카오로 시작하기''로 로그인한 뒤 차량번호를 입력하지 않고 앱을 종료하면, 재실행 시 시작 화면(카카오로 시작하기, 가입없이 시작하기, 로그인하기)이 나오지 않고 차량번호 입력 화면으로 바로 이동함\n사전 조건: 앱 설치 후 첫 실행, 카카오 계정 보유\n재현 방법: 1. ''카카오로 시작하기''로 로그인\n2. 권한 처리 후 차량번호 입력 화면에서 입력하지 않고 앱 종료\n3. 앱 재실행\n4. 첫 화면 확인\n기대 동작: 로그인 상태를 이어서 쓰는 것이 의도라면, 현재 카카오 계정으로 로그인되어 있음을 알려주고 다른 시작 방법(다른 계정 혹은 가입없이 시작)을 선택할 수 있음\n실제 동작: 시작 화면 없이 차량번호 입력 화면이 바로 노출되고, 로그인 상태나 다른 시작 방법에 대한 안내가 없음 (입력 화면 왼쪽 위의 뒤로가기 ''←'' 버튼도 표시되지 않음)\n개선 제안: 재실행 시 ''카카오 계정으로 로그인되어 있어요'' 안내와 함께 ''이어서 등록하기'', ''다른 방법으로 시작하기'' 선택지 제공','1','0','2' WHERE (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) IS NOT NULL AND (SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM issue WHERE project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) AND title='[BUG-04] [앱 시작] 카카오로 시작한 뒤 차량번호 없이 종료하면, 재실행 시 시작 화면 없이 차량번호 입력 화면으로 바로 이동함');
INSERT INTO issue (project_id,reporter_id,assignee_id,title,content,type,status,priority) SELECT (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),(SELECT user_id FROM users WHERE email='dev@idi.test' LIMIT 1),'[BUG-05] [개선] 시작 화면에 별도 ''회원가입'' 진입 버튼이 없음','관련 TC: TC-001\n구분: 개선 건의 사항\n테스트 환경: Galaxy S24 / Android 16 / 앱 버전 2024.10.03\n테스트 데이터: -\n발생 빈도: 5회 중 5회\n심각도: 낮음\n심각도 근거: 카카오 계정이 없는 사용자는 가입 방법을 찾기 어려움\n발견한 문제: 시작 화면에 ''카카오로 시작하기'', ''가입없이 시작하기'', ''로그인하기''만 있고 ''회원가입'' 버튼이 없어, 카카오 계정을 쓰지 않는 사용자는 어떻게 가입하는지 알기 어려움\n사전 조건: 앱 설치 후 첫 실행\n재현 방법: 1. 앱 최초 설치 후 실행\n2. 시작 화면의 버튼 구성 확인\n기대 동작: 카카오 외 가입 방법이 있다면, 시작 화면에서 ''회원가입'' 진입점을 바로 찾을 수 있음\n실제 동작: ''로그인하기'' 외에 회원가입으로 바로 가는 버튼이 없음\n개선 제안: 시작 화면에 ''다른 방법으로 가입하기'' 같은 회원가입 진입점 추가','1','0','2' WHERE (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) IS NOT NULL AND (SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM issue WHERE project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) AND title='[BUG-05] [개선] 시작 화면에 별도 ''회원가입'' 진입 버튼이 없음');
INSERT INTO issue (project_id,reporter_id,assignee_id,title,content,type,status,priority) SELECT (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),(SELECT user_id FROM users WHERE email='dev@idi.test' LIMIT 1),'[재검증 TC-010] 알림 권한 허용 안내 재노출 여부 확인','추가 확인용 이슈(확정 결함 아님). 관련 TC-010. 원본 테스트 결과: Pass. 원본 비고: 재실행 시 알림 권한 허용 안내 팝업 노출. 기대 결과: 권한을 거부해도 차량 등록은 정상 진행되고, 이후 필요한 시점에 권한 허용 안내가 노출된다.','1','0','2' WHERE (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) IS NOT NULL AND (SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM issue WHERE project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) AND title='[재검증 TC-010] 알림 권한 허용 안내 재노출 여부 확인');
INSERT INTO issue (project_id,reporter_id,assignee_id,title,content,type,status,priority) SELECT (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),(SELECT user_id FROM users WHERE email='dev@idi.test' LIMIT 1),'[재검증 TC-021] 차량번호 최대 입력 길이 및 형식 안내 검토','추가 확인용 이슈(확정 결함 아님). 관련 TC-021. 원본 테스트 결과: Pass. 원본 비고: 최대 9자까지만 입력되고 형식 오류 안내가 나오며, 그 외 문제는 없음. 기대 결과: 입력 길이가 제한되거나 형식 오류가 노출되며, 화면이 깨지거나 앱이 멈추지 않는다.','1','0','2' WHERE (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) IS NOT NULL AND (SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM issue WHERE project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) AND title='[재검증 TC-021] 차량번호 최대 입력 길이 및 형식 안내 검토');
