INSERT INTO issue (project_id,reporter_id,assignee_id,title,content,type,status,priority) SELECT (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),(SELECT user_id FROM users WHERE email='dev@idi.test' LIMIT 1),'[재검증 TC-029] 소유자명 공백 처리 정책 확인','추가 확인용 이슈(확정 결함 아님). 관련 TC-029. 원본 테스트 결과: Pass. 원본 비고: 공백을 넣어도 정상적으로 인식함. 기대 결과: 공백이 자동으로 제거되어 정상 조회되거나, 공백 관련 안내가 노출된다.','1','0','2' WHERE (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) IS NOT NULL AND (SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM issue WHERE project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) AND title='[재검증 TC-029] 소유자명 공백 처리 정책 확인');
INSERT INTO issue (project_id,reporter_id,assignee_id,title,content,type,status,priority) SELECT (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),(SELECT user_id FROM users WHERE email='dev@idi.test' LIMIT 1),'[재검증 TC-038] 앱 재실행 시 초기 화면 전환 정책 확인','추가 확인용 이슈(확정 결함 아님). 관련 TC-038. 원본 테스트 결과: Pass. 원본 비고: 재실행 시 초기 화면 노출. 기대 결과: 미완료 정보가 남지 않고 처음 화면부터 다시 진행할 수 있다.','1','0','2' WHERE (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) IS NOT NULL AND (SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM issue WHERE project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) AND title='[재검증 TC-038] 앱 재실행 시 초기 화면 전환 정책 확인');
INSERT INTO issue (project_id,reporter_id,assignee_id,title,content,type,status,priority) SELECT (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),(SELECT user_id FROM users WHERE email='dev@idi.test' LIMIT 1),'[재검증 TC-039] 앱 재실행 시 등록 진행상황 유지 정책 확인','추가 확인용 이슈(확정 결함 아님). 관련 TC-039. 원본 테스트 결과: Pass. 원본 비고: 진행상황이 유지되는 것을 확인. 기대 결과: 복귀 후 진행하던 화면이 유지되거나 처음부터 다시 진행할 수 있으며, 앱이 멈추지 않는다.','1','0','2' WHERE (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) IS NOT NULL AND (SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM issue WHERE project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='앱 최초 차량등록 테스트' ORDER BY project_id LIMIT 1) AND title='[재검증 TC-039] 앱 재실행 시 등록 진행상황 유지 정책 확인');
INSERT INTO project (owner_id,title,description,status,start_date,due_date) SELECT (SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1),'월드크리닝 POS 운영 테스트','실제 세탁 중개 매장에서 POS를 직접 사용하며 기록한 테스트케이스. 일부 최종 결제 단계는 운영 영향으로 미실행.','0',CURRENT_DATE(),DATE_ADD(CURRENT_DATE(),INTERVAL 30 DAY) WHERE NOT EXISTS (SELECT 1 FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트');
