INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-001','POS 프로그램 정상 실행 및 초기 화면 표시','POS 설치 완료, 네트워크 연결 정상, 본사 발급 계정 로그인 완료','접수 화면에 진입하여 초기 공지사항과 행사문자 발송 결과를 확인한다.','프로그램이 정상 실행되고 행사문자 발송 결과·건수 및 공지사항이 표시된다.','0','우선순위: 필수.',CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-002','신규 회원가입','POS 로그인 완료, 중복되지 않는 테스트용 전화번호 준비','접수 > 신규 회원 등록에서 이름·전화번호·성별 입력 후 등록한다.','신규 회원이 등록되고 카카오톡 회원가입 알림이 발송된다.','0','우선순위: 필수.',CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-003','기존 전화번호로 신규 회원가입','등록된 테스트 회원의 전화번호가 존재함','신규 회원 등록에서 동일한 전화번호로 재가입을 시도한다.','전화번호 중복 안내가 표시되고 등록이 차단된다.','0','우선순위: 필수.',CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-004','가입 후 카카오톡 행사 알림 수신 동의 여부','신규 회원가입 완료, 행사 알림 동의 화면 접근 가능','행사문자 수신 미동의를 선택하고 사인패드에서 서명한다.','동의 여부와 관계없이 사인패드 서명 화면이 표시된다.','0','우선순위: 선택.',CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-005','전화번호로 회원 검색','등록된 테스트 회원 존재','접수 화면에서 회원 전화번호 뒷자리를 입력하고 검색한다.','회원 이름·전화번호와 누적 결제금액·미수금·완료 세탁물 개수가 표시된다.','0','우선순위: 필수.',CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-006','회원 이름 수정','TC-002에서 등록한 회원 조회 가능','고객정보 수정에서 테스트 회원 이름을 ''테스트''로 변경한다.','회원 이름이 ''테스트''로 변경된다.','0','우선순위: 필수. 실제 인명은 제외하고 테스트용 명칭으로 표기',CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-007','회원 전화번호 정상 수정','TC-006 이름 수정 완료','고객정보 수정에서 전화번호를 다른 미등록 번호로 변경한다.','이름은 유지되고 전화번호만 변경된다.','0','우선순위: 필수.',CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-008','기존 회원 전화번호로 중복 수정','수정 가능한 테스트 회원과 별도의 기존 회원이 존재함','테스트 회원 전화번호를 다른 기존 회원의 전화번호로 수정하고 해당 번호로 검색한다.','중복 전화번호 경고가 표시되고 수정이 차단된다.','1','우선순위: 필수. 실제 관찰: 기존 회원(가족)과 동일한 전화번호로 수정이 저장됨. 검색 시 이름이 다른 두 회원이 동일 번호로 조회됨. 신규 가입에서는 중복 차단됨.',CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-009','접수 화면에서 회원 탈퇴','TC-008 이후 테스트 회원의 전화번호를 원래 번호로 복구함','테스트 회원 검색 > 고객정보 수정 > 고객 탈퇴를 선택한다.','고객이 탈퇴 처리되고 접수 화면에서 고객 정보가 사라진다.','0','우선순위: 필수.',CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-010','접수 화면에서 탈퇴 회원 복구','TC-009에서 탈퇴 처리한 테스트 회원 존재','탈퇴 회원 전화번호 뒷자리로 검색한 뒤 복원 버튼을 누른다.','고객 정보가 다시 표시되고 세탁물 접수가 가능한 상태가 된다.','0','우선순위: 선택. 회원 탈퇴는 소프트 삭제로 추정',CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-011','회원관리 메뉴에서 회원 탈퇴','전체메뉴 > 회원관리 접근, 별도 관리자 계정 로그인','테스트 회원을 검색하고 목록에서 고객 탈퇴를 누른다.','해당 회원이 탈퇴 처리된다.','0','우선순위: 선택.',CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-012','탈퇴 회원 완전 삭제 기능 확인','회원관리 메뉴에서 탈퇴 고객 필터로 테스트 회원 조회','탈퇴한 테스트 회원의 삭제 버튼을 누른다.','완전 삭제가 허용된다면 회원관리에서 더 이상 조회되지 않는다.','3','우선순위: 선택. 실제 관찰: 탈퇴 후 2년이 지나야 완전 삭제할 수 있다는 안내 메시지가 표시됨. 보존 기간 제한으로 즉시 완전 삭제 불가.',CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-013','전화번호 검색 후 세탁물 접수','활성 상태의 테스트 회원 존재','전화번호 뒷자리 검색 후 세탁물 종류·재질·색상·수량을 선택하고 금액을 확인한다.','선택한 세탁물의 분류·수량·총 가격이 표시되고 접수할 수 있다.','2','우선순위: 필수. 실제 결제 및 코드태그 사용이 발생하므로 최종 결제·접수 단계는 실행하지 않음. 품목 선택 화면까지만 확인.',NULL) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-014','할인 없는 세탁물 접수','할인 제외 품목(와이셔츠) 선택 가능','와이셔츠를 선택하고 접수 화면의 가격을 확인한다.','할인 없이 원래 가격이 표시되고 결제 금액에도 동일하게 적용된다.','2','우선순위: 선택. 최종 결제·접수 단계 미실행(실제 결제 및 코드태그 소모 방지).',NULL) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-015','10% 할인있는 세탁물 접수(요일, 쌈데이 할인)','수요일·토요일 또는 쌈데이 할인 조건 충족, 10% 할인 대상 품목 존재','모직상의를 선택하고 표시된 원가와 할인가를 비교해 원가×0.9와 대조한다.','10% 할인 가격이 표시되고 최종 결제에도 적용된다.','2','우선순위: 선택. 원가·할인가 표시 확인 범위만 테스트. 최종 결제·접수 단계 미실행.',NULL) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-016','20% 할인있는 세탁물 접수(요일, 고객할인)','수요일·토요일 또는 해당 할인 조건 충족, 침구류 20% 할인 대상 품목 존재','면 또는 극세사 이불(소)을 선택하고 원가×0.8과 표시 할인가를 비교한다.','20% 할인 가격이 표시되고 최종 결제에도 적용된다.','2','우선순위: 선택. 원가·할인가 표시 확인 범위만 테스트. 최종 결제·접수 단계 미실행.',NULL) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO test_case (project_id,created_by,case_code,title,precondition,test_steps,expected_result,result,remarks,executed_at) VALUES ((SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'POS-TC-017','10% 할인있는 명품 세탁물 접수(요일 할인)','수요일, 하이엔드케어 10% 할인 대상 품목 선택 가능','하이엔드케어 > 프리미엄 자켓을 선택하고 색상·브랜드 설정 후 원가×0.9와 표시 할인가를 비교한다.','프리미엄 자켓에 10% 할인 가격이 표시되고 최종 결제에도 적용된다.','2','우선순위: 선택. 테스트 당시 수요일. 최종 결제·접수 단계 미실행.',NULL) ON DUPLICATE KEY UPDATE test_case_id=test_case_id;
INSERT INTO issue (project_id,reporter_id,assignee_id,title,content,type,status,priority) SELECT (SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1),(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),(SELECT user_id FROM users WHERE email='dev@idi.test' LIMIT 1),'[POS BUG] 회원정보 수정 시 기존 회원 전화번호 중복 허용','관련 테스트: POS-TC-008\\n재현: 테스트 회원 조회 > 고객정보 수정 > 다른 기존 회원 전화번호 입력 > 저장 > 해당 번호 검색\\n기대: 중복 전화번호 안내 및 저장 차단\\n실제: 수정 저장 성공, 같은 전화번호로 이름이 다른 회원 두 명 검색됨\\n비교: 신규 회원가입 시에는 동일 전화번호 등록이 차단됨\\n비고: 실제 매장 POS 사용 중 발견한 결함. 전화번호 및 인명은 비식별화함.','1','0','2' WHERE NOT EXISTS (SELECT 1 FROM issue WHERE project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1) AND title='[POS BUG] 회원정보 수정 시 기존 회원 전화번호 중복 허용');
INSERT INTO issue_comment (issue_id,user_id,content) SELECT i.issue_id,(SELECT user_id FROM users WHERE email='qa@idi.test' LIMIT 1),'실제 재현 확인: 신규 가입에서는 중복 번호를 차단하지만 회원정보 수정에서는 저장됨. 운영 데이터에 영향을 주지 않도록 테스트 후 번호 복구함.' FROM issue i WHERE i.project_id=(SELECT project_id FROM project WHERE owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND title='월드크리닝 POS 운영 테스트' ORDER BY project_id LIMIT 1) AND i.title='[POS BUG] 회원정보 수정 시 기존 회원 전화번호 중복 허용' AND NOT EXISTS (SELECT 1 FROM issue_comment c WHERE c.issue_id=i.issue_id AND c.content LIKE '실제 재현 확인:%');
INSERT INTO project_member (user_id,project_id,role) SELECT u.user_id,p.project_id,'1' FROM users u JOIN project p ON p.project_id=(SELECT MIN(p2.project_id) FROM project p2 WHERE p2.title='11번가 계정관리' AND p2.owner_id=(SELECT user_id FROM users WHERE email='admin@idi.test' LIMIT 1) AND p2.deleted_at IS NULL) WHERE u.email='seoyeon@idi.test' AND u.deleted_at IS NULL ON DUPLICATE KEY UPDATE role=VALUES(role);
